import { getCleanClone, getRegExpFlags } from './utils';

import type { Cache } from './utils';

export type InternalCopier<Value> = (value: Value, state: State) => Value;

export interface State {
  Constructor: any;
  cache: Cache;
  copier: InternalCopier<any>;
  /**
   * The number of nested objects currently being copied, used to bound traversal
   * of deeply-nested values before the call stack is exhausted.
   */
  depth: number;
  prototype: any;
}

